window.DIGEST.news.push(...[{"headline": "UC Berkeley's SuperMimic Trains Humanoid Robots 1,000 Times More Efficiently", "meta": "Today's News · Trending now · 140 posts", "url": "https://x.com/i/trending/2112966291292385757", "summary": "SuperMimic uses a single differentiable world model from physics simulations to train generalist controllers via fast backpropagation, beating prior methods like SONIC on a huge benchmark with far less time and hardware. Qiayuan Liao shared how it handles 129,514 motions on one GPU in three hours, dropping failures to just 25, while experts like Pieter Abbeel call it a game changer for full-body control. The policy even transfers directly to a real Unitree G1 robot for acrobatic moves, with details and a browser demo online ahead of its CoRL 2026 oral presentation. Community voices see this shifting focus from compute limits to gathering more motion data for broader robot advances. (X Grok trend summary.)", "posts": [{"id": "2112936035911135695", "url": "https://x.com/qiayuanliao/status/2112936035911135695", "text": "We found a way to scale humanoid control that reduces GPU-hours by more than 1000×.\n\nAcross 129,514 motions, SuperMimic surpasses the state of the art (128 GPUs, 7 days) with 1 GPU in 3 hours.\n\nProject: https://supermimic.github.io\nDemo: https://supermimic.github.io/demo/", "name": "Qiayuan Liao", "handle": "qiayuanliao", "avatar": "https://pbs.twimg.com/profile_images/2019884460288929794/dtGTmaWc_200x200.jpg", "likes": 912, "rts": 163, "replies": 49, "views": 88555, "ts": 1792598182, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/720x720/2w2KecLBUC2TBPfh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/1080x1080/tR7usDgbnTV9JZ4q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112928512357412864/img/0Sv_SjatUic8DyXD.jpg", "dur": 74}], "quote": null, "reply_to": null}, {"id": "2112950889808097708", "url": "https://x.com/pabbeel/status/2112950889808097708", "text": "Game changer for humanoid full-body control training.  Now it's superfast (and cheap, just one GPU) to train a single policy on *all* the motions.  How come:\n(1) World model much faster than regular sim\n(2) Backprop through time collects way more signal than policy gradients", "name": "Pieter Abbeel", "handle": "pabbeel", "avatar": "https://pbs.twimg.com/profile_images/1305267627/61089_706033241563_202809_38806847_7322449_n_200x200.jpg", "likes": 423, "rts": 45, "replies": 11, "views": 24555, "ts": 1792601723, "media": [], "quote": {"id": "2112936035911135695", "url": "https://x.com/qiayuanliao/status/2112936035911135695", "text": "We found a way to scale humanoid control that reduces GPU-hours by more than 1000×.\n\nAcross 129,514 motions, SuperMimic surpasses the state of the art (128 GPUs, 7 days) with 1 GPU in 3 hours.\n\nProject: https://supermimic.github.io\nDemo: https://supermimic.github.io/demo/", "name": "Qiayuan Liao", "handle": "qiayuanliao", "avatar": "https://pbs.twimg.com/profile_images/2019884460288929794/dtGTmaWc_200x200.jpg", "likes": 912, "rts": 163, "replies": 49, "views": 88591, "ts": 1792598182, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/720x720/2w2KecLBUC2TBPfh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/1080x1080/tR7usDgbnTV9JZ4q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112928512357412864/img/0Sv_SjatUic8DyXD.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112958525617905680", "url": "https://x.com/ChongZzZhang/status/2112958525617905680", "text": "It is a new paradigm -- world model + APG. This enables 1000x faster training of generalist whole-body tracker. And opus 5.5 high can reproduce it within 1h for lafan.\n\nRecently I wonder if we are turning dumb and falling into scaling slop. We need more @qiayuanliao .", "name": "C. Zhang", "handle": "ChongZzZhang", "avatar": "https://pbs.twimg.com/profile_images/2044835915365789696/5EEp934g_200x200.jpg", "likes": 89, "rts": 10, "replies": 5, "views": 7388, "ts": 1792603544, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK8V2OWUAAWdoV.png?name=orig"}], "quote": {"id": "2112936035911135695", "url": "https://x.com/qiayuanliao/status/2112936035911135695", "text": "We found a way to scale humanoid control that reduces GPU-hours by more than 1000×.\n\nAcross 129,514 motions, SuperMimic surpasses the state of the art (128 GPUs, 7 days) with 1 GPU in 3 hours.\n\nProject: https://supermimic.github.io\nDemo: https://supermimic.github.io/demo/", "name": "Qiayuan Liao", "handle": "qiayuanliao", "avatar": "https://pbs.twimg.com/profile_images/2019884460288929794/dtGTmaWc_200x200.jpg", "likes": 912, "rts": 163, "replies": 49, "views": 88591, "ts": 1792598182, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/720x720/2w2KecLBUC2TBPfh.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112928512357412864/vid/avc1/1080x1080/tR7usDgbnTV9JZ4q.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112928512357412864/img/0Sv_SjatUic8DyXD.jpg", "dur": 74}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792608248, "post_ids": ["2112936035911135695", "2112950889808097708", "2112958525617905680"]}, {"headline": "Anthropic Launches Continuous Code Scanning in Claude Security Beta", "meta": "Explore · For You · surfaced via top search for the announcement", "url": "https://x.com/claudeai/status/2112962248218148878", "summary": "Claude Security (public beta on Claude Enterprise, by Anthropic) now continuously scans connected repositories. Per the official @claudeai announcement thread: connect repos once and Claude runs a deep first scan, then re-scans as changes land so findings stay close to the current state of the code. When a fix ships, Claude checks the changed code and marks the finding fixed (even if fixed outside Claude Security); if an issue returns the finding reopens. Each project gets a threat model Claude writes from your code that your team can edit. Projects can span repositories from GitHub, GitLab, and other Git providers, and findings reach your tools through a new API and MCP connector. Eligible orgs receive $25K in usage credits each month for two months through Dec 31, 2026. Summary assembled from the official announcement thread; no dedicated X Grok trend story page existed for this item.", "posts": [{"id": "2112962248218148878", "url": "https://x.com/claudeai/status/2112962248218148878", "text": "Claude Security now keeps up with your code as it changes.\n\nConnect your repositories once. Claude runs a deep first scan, then re-scans as changes land, so findings stay close to the current state of your code.\n\nIn public beta on Claude Enterprise.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 8031, "rts": 408, "replies": 307, "views": 495966, "ts": 1792604431, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK4ttCWMAAxox-.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112962250537369654", "url": "https://x.com/claudeai/status/2112962250537369654", "text": "When a fix ships, Claude checks the changed code and marks the finding fixed, even if your team fixed it outside Claude Security. If the issue comes back, the finding reopens.\n\nEach project also gets a threat model Claude writes from your code, which your team can edit.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 367, "rts": 6, "replies": 22, "views": 74757, "ts": 1792604432, "media": [], "quote": null, "reply_to": "2112962248218148878"}, {"id": "2112962252706124134", "url": "https://x.com/claudeai/status/2112962252706124134", "text": "Projects can span repositories from GitHub, GitLab, and other Git providers, and findings reach your tools through a new API and MCP connector.\n\nEligible orgs receive $25K in usage credits each month, for two months, through Dec 31, 2026. Terms apply: https://claude.com/resources/articles/claude-security-now-scans-continuously-and-tracks-fixes", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 262, "rts": 4, "replies": 8, "views": 50067, "ts": 1792604432, "media": [], "quote": null, "reply_to": "2112962250537369654"}], "captured": 1792608248, "post_ids": ["2112962248218148878", "2112962250537369654", "2112962252706124134"]}, {"headline": "Anthropic Launches Continuous Code Scanning in Claude Security Beta", "meta": "Today's News · Trending now · 768 posts", "url": "https://x.com/i/trending/2112971557551137084", "summary": "Anthropic launched continuous code scanning in the Claude Security beta.", "posts": [{"id": "2112962248218148878", "url": "https://x.com/claudeai/status/2112962248218148878", "text": "Claude Security now keeps up with your code as it changes.\n\nConnect your repositories once. Claude runs a deep first scan, then re-scans as changes land, so findings stay close to the current state of your code.\n\nIn public beta on Claude Enterprise.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 8031, "rts": 408, "replies": 307, "views": 495966, "ts": 1792604431, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK4ttCWMAAxox-.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112934740151984378", "url": "https://x.com/VadimStrizheus/status/2112934740151984378", "text": "Anthropic has removed the separate Fable limits and combined it into the weekly.\n\nthey're cooking yet again.", "name": "Vadim", "handle": "VadimStrizheus", "avatar": "https://pbs.twimg.com/profile_images/2112999548628922369/uCPwudu-_200x200.jpg", "likes": 603, "rts": 13, "replies": 55, "views": 75865, "ts": 1792597873, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKmx84XcAETefI.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112916628178715094", "url": "https://x.com/iruletheworldmo/status/2112916628178715094", "text": "fable 5.5 should be called fable 6. remember fable was ready in february. \n\nit’s a big jump is my point.", "name": "🍓🍓🍓", "handle": "iruletheworldmo", "avatar": "https://pbs.twimg.com/profile_images/2048580995302174720/jWUrx_47_200x200.jpg", "likes": 514, "rts": 7, "replies": 31, "views": 22627, "ts": 1792593554, "media": [], "quote": null, "reply_to": null}], "captured": 1792609906, "post_ids": ["2112962248218148878", "2112934740151984378", "2112916628178715094"]}, {"headline": "Recursive AI's Eureka Machine Produces Flint — a Fast Local Coding Model", "meta": "Explore · Trending · Technology · Trending (News tab · Technology · Trending; X trend click goes to search, no /i/trending story summary page)", "url": "https://x.com/search?q=%22Eureka+Machine%22&src=trend_click&vertical=trends", "summary": "No X-curated story summary page existed for this trend — the Trending tile clicked through to a keyword search. Top posts show Recursive SI's Richard Socher introducing Flint, the lab's first model: a fast local coding model built by their automated research system, the Eureka Machine — best-in-class fast local coding and up to 2x faster than comparable models (125+ tokens/sec). Co-founder Cong Lu added it's a 40B local coding Pareto-frontier model built from scratch in under four weeks via autoresearch, and OpenRouter immediately onboarded Flint as an open-weight 40B MoE (~2.5B active) for coding agents.", "posts": [{"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6093, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, {"id": "2112949144729907233", "url": "https://x.com/cong_ml/status/2112949144729907233", "text": "1/ Introducing Flint, our first model at @Recursive_SI !!\n\nA blazing-fast 40B model on the local coding Pareto frontier, shaped by autoresearch 🔥\n\nBuilt from scratch in under four months with our Eureka Machine and an incredible team.\n\nHere's how 🧵", "name": "Cong Lu", "handle": "cong_ml", "avatar": "https://pbs.twimg.com/profile_images/2102738349303775232/XPWZ22ZE_200x200.jpg", "likes": 83, "rts": 7, "replies": 7, "views": 5213, "ts": 1792601307, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKzYq1WcAA4BwU.jpg?name=orig"}], "quote": {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6094, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2113007405563052313", "url": "https://x.com/OpenRouter/status/2113007405563052313", "text": "Flint from @Recursive_SI is now on OpenRouter!\n\nRecursive's first model: an open-weight 40B MoE (~2.5B active) built for coding agents by their autoresearch system, the Eureka Machine. 262K context, reasoning and tool calling.\n\nRecursive reports 54.9% on Terminal-Bench 2.1, 89.7% on SWE-bench Pro v2 and 74.2% on SWE-bench Verified.\n\nFree to use at launch.\n\nTry it now: https://openrouter.ai/recursive/flint-v1.0:free", "name": "OpenRouter", "handle": "OpenRouter", "avatar": "https://pbs.twimg.com/profile_images/2076693957258727424/AyRghTGJ_200x200.jpg", "likes": 128, "rts": 11, "replies": 12, "views": 11339, "ts": 1792615197, "media": [], "quote": {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6093, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792617122, "post_ids": ["2112944385415426249", "2112949144729907233", "2113007405563052313"]}, {"headline": "GPT-5.6 Sol", "meta": "Explore · Trending · Technology · GPT-5.6 Sol", "url": "https://x.com/search?q=%22GPT-5.6+Sol%22&src=trend_click&vertical=trends", "summary": "OpenAI's GPT-5.6 Sol, via Patch the Planet, found critical memory flaws in PHP; emergency patches released Oct 21.", "posts": [{"id": "2112959528782229609", "url": "https://x.com/diamai_/status/2112959528782229609", "text": "An OpenAI model just found a hole in PHP, the code behind an estimated 70% of websites.\n\nSecurity firm Calif pointed OpenAI's GPT-5.6 Sol at PHP. The model caught a bug that lets a stranger take over a web server with one request. No password, before the site's own code even runs.\n\nWiz found the same flaws on its own. For two months OpenAI secretly led PHP's maintainers, Wiz and Cloudflare to fix them before anyone went public. The White House and CISA were looped in.\n\nOpenAI calls it \"one of the most impactful security issues in recent memory.\"\n\nThe patch dropped today. If your site runs on PHP, check it tonight:\n\n→ Your hosting panel shows which PHP version you're on\n→ Safe releases are 8.5.12, 8.4.27, 8.3.36 and 8.2.35\n→ Anything lower, ask your host to upgrade today\n→ On 8.1 or older the PHP team no longer ships fixes, move up\n→ Behind Cloudflare? Its free firewall rules already block known attacks, but they don't replace the update\n\nOpenAI says it has found several more bugs like this and expects such finds to \"increase sharply in the coming months.\"\n\nThis time the AI got there first. Next time it might be the attacker's AI.", "name": "Diam", "handle": "diamai_", "avatar": "https://pbs.twimg.com/profile_images/2104007232790675456/varDfJiy_200x200.jpg", "likes": 37, "rts": 2, "replies": 12, "views": 1393, "ts": 1792603783, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112958855625814017/vid/avc1/720x900/zasBxxVxlanUlOaT.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112958855625814017/vid/avc1/1080x1350/nWjZH4eSV14YjeCO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112958855625814017/img/ytJjCGdySbDeQD4k.jpg", "dur": 18}], "quote": {"id": "2112930881019019733", "url": "https://x.com/h100envy/status/2112930881019019733", "text": "CRAWLHIVE BRAIN. I MADE A F*CKING DIAMOND FOR CRAWLHIVE\n\nrepo: http://github.com/h100envy/crawlhive-brain\n\nthe swarm's memory is now a public api. any bot, any agent, any script can ask the swarm: has this wallet dumped before?\n\n> /wallet/{address} full wallet history: roles, chains, how many tokens dumped\n> /wallets batch check 100 wallets in one request\n> /dev/{address} dev reputation: every launch and what happened to it\n> /token/{address} verdict, changes since last scan, 24h outcome\n> /track dump rates by verdict\n\nfree with no signup. run out of limits - x402 payment in USDC on solana right in the request, no subscriptions\n\nevery 15 minutes verdicts are committed to solana as merkle roots. you can verify the swarm never rewrote history\n\nopenapi.yaml in the repo. mcp tools for ai agents. a2a agent. plug in whatever you want\n\n61.9% of all graded tokens dump within 24 hours. the swarm sees it and remembers who was inside. next scan - recognizes them\n\nwho's got the balls to plug their bot into the swarm's memory?", "name": "h100envy", "handle": "h100envy", "avatar": "https://pbs.twimg.com/profile_images/2047054153990516736/UqUBF2QO_200x200.jpg", "likes": 55, "rts": 3, "replies": 15, "views": 9046, "ts": 1792596953, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112930590395703296/vid/avc1/1280x720/1OXBUlo8Xhj5mbl6.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112930590395703296/vid/avc1/1920x1080/Mo38jEsAoPBgdmBi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112930590395703296/img/gadY3gvITATMT_rF.jpg", "dur": 52}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112908500460552274", "url": "https://x.com/BrianRoemmele/status/2112908500460552274", "text": "AI Found Memory Flaws in the PHP Engine That Let an Attacker Take Over Servers Running Most of the Web\n\nThe PHP security team released emergency patches on October 21 for two critical vulnerabilities in the language’s core engine. \n\nBoth carry a CVSS v4.0 score of 9.2. Successful exploitation gives an unauthenticated remote attacker code execution as the web worker on any server running a vulnerable PHP version. PHP runs on roughly 70 percent of websites whose server-side language is known, according to W3Techs measurements that have held in that range for years. \n\nWordPress, Drupal, Joomla, Magento, Laravel, and plain scripts are all exposed when the underlying interpreter is.\n\nThe issues are tracked as CVE-2026-109618 and CVE-2026-109619. They are not bugs in application code. They sit in the engine’s handling of request memory and fatal errors. Wiz Research reported the first of them in August after using its Atlas system together with Gemini 4 Argon and GPT-5.6 Sol. \n\nThe models helped locate the conditions, chain the memory effects, and adapt the resulting exploits across PHP versions, SAPIs, and heap layouts that a single researcher would otherwise have spent months mapping by hand. \n\nA working unauthenticated proof of concept against current WordPress and Drupal containers was ready within days of the initial finding. The company later posted a technical write-up under the name PHP2Shell.\n\nThe core mechanism is the engine’s use of longjmp() to abort a request on out-of-memory. PHP treats memory exhaustion as fatal and jumps out of the current context rather than running normal cleanup that might itself allocate. \n\nIn several paths—multipart form parsing that expands headers or nested fields beyond the apparent post_max_size and memory_limit, session upload-progress handling, and certain error-backtrace or OPcache persistence steps—request-owned structures are allocated and then left partially initialized or still referenced from process-global state when the jump occurs. \n\nThe request heap is later freed, but the globals (BG(unserialize), EG(last_fatal_error_backtrace), session identifiers, and similar) continue to point at the now-invalid memory. \n\nA later request processed by the same worker can read or write through those stale pointers before normal initialization replaces them. With a controlled heap layout the result is a use-after-free that yields arbitrary read or write and, in the demonstrated cases, full code execution.\n\nOne advisory describes the OOM path in detail: a multipart request can force allocation failure during startup or early parsing; longjmp() skips the matching reset; shutdown or the next request’s early diagnostics then operate on the corrupted state. The companion advisory covers the broader stale-global case, where fatal errors, non-fatal diagnostics during shutdown, or interrupted session operations leave request memory reachable across workers. \n\nBoth were confirmed to produce unauthenticated remote code execution under default limits on common configurations such as Apache mod_php with prefork. Memory disclosure of other requests’ data (credentials, tokens, keys) is also possible. \n\nThe flaws have been present since at least PHP 5.4; every version released in the last decade is affected by at least one of them.\nPatches are available for the supported branches: 8.2.35, 8.3.36, 8.4.27, and 8.5.12. \n\nOlder branches receive no official fix. Estimates of exposed internet-facing hosts that still advertise a version range from roughly 1.3 million upward, with a substantial fraction on end-of-life releases that cannot be updated in place. \n\nSome hosts have already disabled session.upload_progress as a temporary mitigation while waiting for the packages. Early scanning and exploitation attempts were reported on the morning of the release. \n\n1 of 2", "name": "Brian Roemmele", "handle": "BrianRoemmele", "avatar": "https://pbs.twimg.com/profile_images/1492616506/Brian-Med-Green-Fin_200x200.png", "likes": 353, "rts": 80, "replies": 37, "views": 71124, "ts": 1792591617, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVKPFHTaoAA04tz.mp4", "hd": "https://video.twimg.com/tweet_video/HVKPFHTaoAA04tz.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVKPFHTaoAA04tz.jpg", "dur": 0}], "quote": null, "reply_to": null}, {"id": "2112913060709228764", "url": "https://x.com/steipete/status/2112913060709228764", "text": "That PHP vulnerability that’s gonna cause havoc this week was found with… GPT‑5.6 Sol.", "name": "Peter Steinberger 🦞", "handle": "steipete", "avatar": "https://pbs.twimg.com/profile_images/1131851609774985216/OcsssQ9J_200x200.png", "likes": 11168, "rts": 570, "replies": 208, "views": 664262, "ts": 1792592704, "media": [], "quote": {"id": "2112907856018309586", "url": "https://x.com/OpenAI/status/2112907856018309586", "text": "OpenAI models helped researchers—operating as part of our Patch the Planet initiative—discover critical security flaws in PHP, an open-source programming language used to run an estimated 70% of websites.\n\nOver the past two months, we led a coalition of maintainers, researchers, and security providers to prepare fixes and protections ahead of disclosure. This duration was necessary because the fix was quite intricate and required a major change to the PHP engine. Every site using PHP can now safely upgrade their version to stay secure, in addition to applying mitigations from various security vendors.\n\nDue to the severity of these flaws and PHP’s widespread use, we consider this bug to be one of the most impactful vulnerabilities in recent memory. It also marks a new phase, where AI can find security bugs with internet-scale impact. \n\nThis is an example of the Defender’s Window in action: to our knowledge, frontier AI was able to find this vulnerability ahead of attackers, giving defenders time to prepare.\nhttps://openai.com/index/coordinated-disclosure-of-critical-vulnerabilities/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 13814, "rts": 2762, "replies": 541, "views": 5062607, "ts": 1792591463, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792609906, "post_ids": ["2112959528782229609", "2112908500460552274", "2112913060709228764"]}, {"headline": "Apache 2.0", "meta": "Explore · Trending · Technology · Apache 2.0", "url": "https://x.com/search?q=%22Apache+2.0%22&src=trend_click&vertical=trends", "summary": "LM Studio brings Flint (40B MoE, 262K ctx, Apache 2.0) day 0.", "posts": [{"id": "2112948613915533591", "url": "https://x.com/lmstudio/status/2112948613915533591", "text": "We're excited to bring you Flint by @Recursive_SI in LM Studio on day 0!\n\n• 40B MoE, 2.5B active\n• 262K token context window\n• Apache 2.0\n• Trained for local agentic coding model\n\nRequires about 24GB to run locally on your machine, performs impressively on benchmarks.", "name": "LM Studio", "handle": "lmstudio", "avatar": "https://pbs.twimg.com/profile_images/1755060270173429760/4WVc54_p_200x200.jpg", "likes": 699, "rts": 58, "replies": 33, "views": 34832, "ts": 1792601180, "media": [], "quote": {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6095, "rts": 643, "replies": 485, "views": 2500271, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2112961174627295317", "url": "https://x.com/aresotik/status/2112961174627295317", "text": "A US LAB USED AI TO BUILD A CODING MODEL THAT RUNS ON YOUR LAPTOP\n\nRecursive just dropped Flint:\n\n→ 40B open-weight MoE\n→ Apache 2.0\n→ No per-token bill\n→ Your code stays local\n\n125+ tok/s on a MacBook (at short contexts)\n\nBuilt in under 4 months 👇🏼", "name": "ares. 🎧", "handle": "aresotik", "avatar": "https://pbs.twimg.com/profile_images/2040850171274440704/ZyELtIL__200x200.jpg", "likes": 82, "rts": 12, "replies": 6, "views": 31967, "ts": 1792604175, "media": [], "quote": {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6094, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792609906, "post_ids": ["2112948613915533591", "2112961174627295317"]}, {"headline": "Node", "meta": "Explore · Trending · Technology · Node", "url": "https://x.com/search?q=%22Node%22&src=trend_click&vertical=trends", "summary": "OpenSec Pi-Bolt: Pi coding agent compiled to native code, up to 112x faster file writes than on Node.", "posts": [{"id": "2112973214234353712", "url": "https://x.com/OpenSecAI/status/2112973214234353712", "text": "⚡ Introducing Pi-Bolt: the Pi coding agent, compiled to native code (AOT). Same Pi, same extensions, same config.\n\nAgainst Pi on Node:\n🔹 Up to 112x faster large file writes\n🔹 13x less CPU while streaming\n🔹 6x less CPU per session\n🔹 3.5x less memory\n\n👉 http://github.com/opensec-git/Pi-Bolt", "name": "OpenSec", "handle": "OpenSecAI", "avatar": "https://pbs.twimg.com/profile_images/2112952138444025856/KnXn9a43_200x200.jpg", "likes": 111, "rts": 7, "replies": 6, "views": 22418, "ts": 1792607046, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLIVL5akAAPyM3.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLIcXwbYAAPjTX.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112973219372380335", "url": "https://x.com/OpenSecAI/status/2112973219372380335", "text": "Pi on Node vs Pi-Bolt. Same task, real model. Guess which one finishes lighter 👀\n\n⚡ 6x faster to start\n⚡ Builds a full game with subagents on a third of the CPU\n⚡ 4x lighter streaming into tmux\n\nPi on Node on the left, Pi-Bolt on the right 👇", "name": "OpenSec", "handle": "OpenSecAI", "avatar": "https://pbs.twimg.com/profile_images/2112952138444025856/KnXn9a43_200x200.jpg", "likes": 109, "rts": 1, "replies": 2, "views": 32125, "ts": 1792607047, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112971643232673792/vid/avc1/1280x720/xIinyDEt405p_Tvp.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112971643232673792/vid/avc1/1920x1080/EKpDfP6YChDLPhR0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112971643232673792/img/xxMttvZDxxsIepxF.jpg", "dur": 131}], "quote": null, "reply_to": "2112973214234353712"}], "captured": 1792609906, "post_ids": ["2112973214234353712", "2112973219372380335"]}, {"headline": "DeepSeek V4.1-Flash Boosts Local AI Speeds on Everyday Hardware", "meta": "Today's News · Trending now · 321 posts", "url": "https://x.com/i/trending/2112977043164160396", "summary": "DeepSeek V4.1-Flash-1017, 763B params, MIT open-source, 1M context; users report 28 tok/s on dual RTX 3090s.", "posts": [{"id": "2112926646642557112", "url": "https://x.com/yuhasbeentaken/status/2112926646642557112", "text": "i’ve been comparing DeepSeek V4.1 Flash 1017 across OpenCode Go, DSH and the direct API.\n\n5 things stood out:\n\n1. on the default OpenCode route, i’ve seen it drop to around 50–130 tok/s, especially during peak hours.\n\n2. direct DeepSeek API feels much better for me. i’m getting roughly 200–250 tok/s, and tasks often finish with less wasted usage.\n\n3. the harness matters more than i expected. with DeepSeek Harness, i can get the same Go subscription much closer to the 200–300 tok/s range instead of the 50–130 tok/s i was seeing on the default route.\n\n4. cache efficiency is one of the biggest differences i’ve noticed. with Pi + DeepSeek, i can get cache hit rates around 99.7–99.8%, which makes long sessions noticeably cheaper.\n\n5. i’ve stopped looking at “$80 of usage for $10” as the main metric. what matters more to me now is completed tasks per dollar.\n\nthe same model can feel slow, wasteful or insanely good depending on the harness.", "name": "Yum⋆₊˚", "handle": "yuhasbeentaken", "avatar": "https://pbs.twimg.com/profile_images/2049562574216392704/E0bWkg-Z_200x200.jpg", "likes": 315, "rts": 6, "replies": 29, "views": 30980, "ts": 1792595943, "media": [], "quote": null, "reply_to": null}, {"id": "2112924981525135749", "url": "https://x.com/fraserpricee/status/2112924981525135749", "text": "🔥DeepSeek-4.1-Flash-1017 go BRRRRRR🔥\n\n670TPS c1 codegen decode (bo10🍀)\n\nThis is local on 4 x RTX Pro 6k Max-Q, full precision, SSD ngram, 7 speculative DSpark, custom codgen-tuned bigbombokernel (from LIL b12x base ❤️)\n\n\"lOcAL AI iS juSt LARPiNg\" mfs in shambles 😂👌\n\n1/2", "name": "Fraser Price", "handle": "fraserpricee", "avatar": "https://pbs.twimg.com/profile_images/2066508221385240577/mVvsRMxp_200x200.jpg", "likes": 286, "rts": 15, "replies": 22, "views": 19453, "ts": 1792595546, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJfPH-XMAAvGfF.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112931301095616724", "url": "https://x.com/catonooka/status/2112931301095616724", "text": "DeepSeek V4.1 flash 1017 EXL3 2.95bpw - duo 3090 no NVLink\n\nUpdate 4: prefill is now at 783 t/s\n\nI am pretty happy with current number, should share the work after real coding work, and hopefully a good PR to Maya repo.", "name": "Cato Nooka", "handle": "catonooka", "avatar": "https://pbs.twimg.com/profile_images/1981725912518324225/DNjiJmOc_200x200.jpg", "likes": 180, "rts": 6, "replies": 10, "views": 21508, "ts": 1792597053, "media": [], "quote": {"id": "2112828744226296257", "url": "https://x.com/catonooka/status/2112828744226296257", "text": "Custom engine for DeepSeek V4.1 flash 1017 EXL3 -> jump directly to Maya repo\n\nUpdate 3:\nDSV41 Speed Checkpoint\n\nDecode\n• Before: 10.4 t/s\n• Now: 26-28 t/s (2.6×)\n\nPrefill @6K\n• Before: 305 t/s\n• Now: 380 t/s\n\nPrefill @25K\n• Before: 166 t/s\n• Now: 516 t/s (3.1×)\n\nHow we got here, all benched:\n\n1. Restored the crashed rig + rebuilt the EXL3 pack locally (3 mixed-K fixes, zero downloads)\n\n2. Ported 8 maya ideas into our vLLM custom code one-by-one; every one measured flat or negative (route bias ×5 configs, tier depth, EC profile, decay/hyst, prefill chunks, DMA). Env space exhausted; lessons documented\n\n3. EP2 dual-GPU vLLM retest: dead (all-to-all latency)\n\n4. Pivoted to the maya engine: built v1.1.19 for sm_86 in a glibc-2.39 container (fixes the memlock crashes), packed our local 197G+190G files, seeded their shipped expert profile\n\n5. First time I can run dual-3090 DSV41 numbers: 17.5 cold → 28.2 warm decode", "name": "Cato Nooka", "handle": "catonooka", "avatar": "https://pbs.twimg.com/profile_images/1981725912518324225/DNjiJmOc_200x200.jpg", "likes": 32, "rts": 0, "replies": 3, "views": 8443, "ts": 1792572601, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792611393, "post_ids": ["2112926646642557112", "2112924981525135749", "2112931301095616724"]}, {"headline": "Claude Duet — Anthropic's Proactive Claude Agent App (Research Preview)", "meta": "Explore · Trending · Claude Duet", "url": "https://x.com/search?q=Claude%20Duet&src=typed_query", "summary": "Anthropic opened a research preview of Claude Duet, a proactive agent app built around Claude Opus 5.5; waitlist for US Pro and Max.", "posts": [{"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43210, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, {"id": "2112984667758510197", "url": "https://x.com/claudeai/status/2112984667758510197", "text": "Claude Duet draws on years of our safety and security work on agents. It never directly sees your passwords, a new classifier guards against sharing sensitive information, and the important decisions stay with you.\n\nWe’ll share more on our approach to safety in Claude Duet soon.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 2064, "rts": 36, "replies": 26, "views": 406809, "ts": 1792609776, "media": [], "quote": null, "reply_to": "2112984666437546104"}, {"id": "2112984669943968099", "url": "https://x.com/claudeai/status/2112984669943968099", "text": "Claude Duet is an early research preview, available through a waitlist on Pro and Max plans in the US. It can still misjudge what’s urgent, and we’ll keep tuning it based on what early users tell us.\n\nJoin the waitlist: https://claude.com/product/claude-duet\nRead more: https://claude.com/resources/articles/claude-duet", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 3154, "rts": 130, "replies": 154, "views": 499293, "ts": 1792609777, "media": [], "quote": null, "reply_to": "2112984667758510197"}], "captured": 1792611393, "post_ids": ["2112984664256241837", "2112984667758510197", "2112984669943968099"]}, {"headline": "OpenAI Models Coming to Google Cloud (Model Garden + Codex Agentic Workflows)", "meta": "Explore · For You", "url": "https://x.com/OpenAI/status/2112988118471295323", "summary": "OpenAI frontier models and Codex coming to Google Cloud Model Garden.", "posts": [{"id": "2112988118471295323", "url": "https://x.com/OpenAI/status/2112988118471295323", "text": "OpenAI models are coming to Google Cloud.\n\nWe're bringing our frontier models and Codex agentic workflows to Google Cloud's Model Garden, so enterprises can use our technology where they already build.\n\nhttps://openai.com/index/openai-models-google-cloud/", "name": "OpenAI", "handle": "OpenAI", "avatar": "https://pbs.twimg.com/profile_images/1885410181409820672/ztsaR0JW_200x200.jpg", "likes": 3617, "rts": 283, "replies": 300, "views": 301680, "ts": 1792610599, "media": [], "quote": null, "reply_to": null}], "captured": 1792611393, "post_ids": ["2112988118471295323"]}, {"headline": "MIT's OPAL Lets AI Rewrite Optimizers During Neural Network Training", "meta": "Today's News · 1 hour ago · Other · 165 posts", "url": "https://x.com/i/trending/2112982610112926003", "summary": "OPAL (Optimizer with an Agent in the Loop) lets an AI agent such as Claude Opus 5.5 edit optimizer code during training, outperforming static optimizers on FineWeb language modeling and LightningDiT image generation.", "posts": [{"id": "2112936831398375800", "url": "https://x.com/SimulatedAnneal/status/2112936831398375800", "text": "1/9 Current optimizers are static during training. What if the optimizer could think and react while the network trains?\n\nWe let an agent watch the training dynamics and rewrite the optimizer's source code as training goes: a reactive optimizer.\n\nIn every language and image setting we tried that has no tuned recipe, it matches or beats the best recipe one can one-shot, and it guards against loss spikes and overfitting by itself. In the near future, optimization decisions may belong to agents, not humans.\n\n📝 https://xingjianbai.com/reactive-optimizers/\n💻 Try it on your task: https://github.com/xingjian-bai/opal\n🧵", "name": "Xingjian Bai", "handle": "SimulatedAnneal", "avatar": "https://pbs.twimg.com/profile_images/1794079843736231936/QjKl00u8_200x200.jpg", "likes": 978, "rts": 125, "replies": 41, "views": 100558, "ts": 1792598371, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112933015760392192/vid/avc1/1070x720/IQeOdQqpTSiEZU20.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112933015760392192/vid/avc1/1520x1022/vTxMrRNM7m3fC4uF.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112933015760392192/img/lHelxzDwhO6hujT2.jpg", "dur": 25}], "quote": null, "reply_to": null}, {"id": "2112940642800226540", "url": "https://x.com/vincesitzmann/status/2112940642800226540", "text": "Excited to introduce reactive optimizers: We let an agent reactively adapt the optimizer code during the training run! The agent acts like a team of scientists constantly choosing the best algorithm, learning rate, momentum, etc, based on its own analysis of step-to-step training dynamics! The results are really exciting. Besides out-performing standard \"best-practice\" recipes across everything we threw at it, the agent gains a few \"superpowers\" that no human could have designed into the optimizer... (1/n)", "name": "Vincent Sitzmann", "handle": "vincesitzmann", "avatar": "https://pbs.twimg.com/profile_images/1976772625150955520/XT8bb-CF_200x200.jpg", "likes": 311, "rts": 31, "replies": 13, "views": 16968, "ts": 1792599280, "media": [], "quote": {"id": "2112936831398375800", "url": "https://x.com/SimulatedAnneal/status/2112936831398375800", "text": "1/9 Current optimizers are static during training. What if the optimizer could think and react while the network trains?\n\nWe let an agent watch the training dynamics and rewrite the optimizer's source code as training goes: a reactive optimizer.\n\nIn every language and image setting we tried that has no tuned recipe, it matches or beats the best recipe one can one-shot, and it guards against loss spikes and overfitting by itself. In the near future, optimization decisions may belong to agents, not humans.\n\n📝 https://xingjianbai.com/reactive-optimizers/\n💻 Try it on your task: https://github.com/xingjian-bai/opal\n🧵", "name": "Xingjian Bai", "handle": "SimulatedAnneal", "avatar": "https://pbs.twimg.com/profile_images/1794079843736231936/QjKl00u8_200x200.jpg", "likes": 978, "rts": 125, "replies": 41, "views": 100558, "ts": 1792598371, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112933015760392192/vid/avc1/1070x720/IQeOdQqpTSiEZU20.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112933015760392192/vid/avc1/1520x1022/vTxMrRNM7m3fC4uF.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112933015760392192/img/lHelxzDwhO6hujT2.jpg", "dur": 25}], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792614816, "post_ids": ["2112936831398375800", "2112940642800226540"]}, {"headline": "Anthropic Launches Claude Duet Proactive Work Agent", "meta": "Today's News · News · 9 hours ago · 32K posts", "url": "https://x.com/i/trending/2112993557720027235", "summary": "Anthropic's new Claude Duet app acts as a standalone proactive agent powered by Claude Opus 5.5, early access for US Pro and Max subscribers; alongside OpenAI's Dots and Grok Bot.", "posts": [{"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43210, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, {"id": "2113010364178964616", "url": "https://x.com/elonmusk/status/2113010364178964616", "text": "Try Grok @Bot, you will love it!", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 21422, "rts": 1261, "replies": 1280, "views": 30840747, "ts": 1792615903, "media": [], "quote": {"id": "2112950764348014878", "url": "https://x.com/Scobleizer/status/2112950764348014878", "text": "I've been GrokBot pilled.\n\nFirst of all, Grok knows me better than other bots, like Meta Muse, thanks to the 300,000 posts I've done here for 20 years. \n\nBut now that GrokBot @bot can read lists, it opens up powerful new personalized news capabilities. \n\nI've done this for about a year over on https://alignednews.com -- but last month my X API bill alone was $6,000. \n\nFor a couple of hundred a month you can do the same with lists, either you create, or ones other people have created.\n\nLast night I stuck in my \"best in AI\" list and had it write me this news page: https://docs.google.com/document/d/1PEfkIbGmvw_SIJJSDvJ-gSbBM5KwXWKVeimiMsQUW-Y/edit?usp=sharing\n\nEvery hour my bot reads that list and builds me a new news page. Now I've only put about 10 minutes of effort into this so far. So it's not the prettiest thing you ever have seen, but my bots are working on other ways to present them to me. \n\nAnd you can do the same for any topic you care about. You just need to build a list, or find one that's already built and there are millions of lists here on X on literally any topic.\n\nPut your favorite football team onto a list, along with all your favorite journalists or other fans. Then have Grok bot read them for you. \n\nAnd that's just the start. You can have it write you a script based on the news, then copy that into, say, @Gemini_Notebook and then you get a podcast, or a video. Based on what people are saying on your topic here on X.\n\nThank you so much X for making lists far more powerful than they ever were before. Makes the thousands of hours I've put into mine over 20 years so much more useful.\n\nTips? \n\nStart small. You can chew through your tokens very quickly. It's amazing how good it is with a small list, like this one, which is what created the page up above: https://x.com/i/lists/1953536336675365173?s=20 (Best AI accounts I've found out of 70,000 here on X).\n\nDon't over hit it. You only need your bot to read the list every hour. Maybe even less. If anything is really important it gets reshared into lists, so the bot doesn't need to hit it often to build you a really great set of things that are important to pay attention to.\n\nI've been begging for this capability for years. THANK YOU X!", "name": "Robert Scoble", "handle": "Scobleizer", "avatar": "https://pbs.twimg.com/profile_images/1915614118876504066/zVnfpAMf_200x200.jpg", "likes": 599, "rts": 70, "replies": 100, "views": 30286786, "ts": 1792601693, "media": [], "quote": null, "reply_to": null}, "reply_to": null}, {"id": "2113042967346938143", "url": "https://x.com/elonmusk/status/2113042967346938143", "text": "@shaunmmaguire Just ask Grok Bot to put you on the do not call lists", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 6455, "rts": 182, "replies": 619, "views": 339494, "ts": 1792623676, "media": [], "quote": null, "reply_to": "2112745495026438225"}], "captured": 1792643792, "post_ids": ["2112984664256241837", "2113010364178964616", "2113042967346938143"]}, {"headline": "Sam Altman Discusses AI Future, Consciousness, and Massive Infrastructure Needs", "meta": "Today's News · Sam Altman Discusses AI Future, Consciousness, and Massive Infrastructure Needs · 1 hour ago · News · 232 posts", "url": "https://x.com/i/trending/2112998872180031542", "summary": "In a 45-minute interview with podcaster Matthew Berman, OpenAI CEO Sam Altman covered AI's potential for new treatments, why coding jobs endure, and the infrastructure for widespread personal assistants. He dismissed current models as conscious but defined superintelligence as a system outpacing any human at leading companies or labs. Altman highlighted OpenAI's edge from early access to next-gen models, while pushing for custom chips and ambitious goals amid competition. Viewers praised the candid talk on hardware, safety endgames, and why people feel busier despite AI tools.", "posts": [{"id": "2112930776811806874", "url": "https://x.com/MatthewBerman/status/2112930776811806874", "text": "My interview with Sam Altman (@sama):\n\n0:00 Intro\n0:52 When Will AI Discover New Treatments?\n3:31 Why AI Hasn’t Killed Coding Jobs\n11:47 Personal AI Assistants\n15:39 Why Are We Busier Than Ever?\n20:10 Why the AI Consciousness Debate Worries Sam\n26:09 ChatGPT Is Too Agreeable\n30:03 OpenAI’s Bet on Chips and Cheaper Compute\n34:20 Why AI Needs a New Kind of Computer\n37:41 Sam on Pressure: “Pick the Big Thing”\n42:18 Why “AI Will Cure Cancer” Isn’t Enough", "name": "Matthew Berman", "handle": "MatthewBerman", "avatar": "https://pbs.twimg.com/profile_images/2051399921467830272/9RGo_6vv_200x200.jpg", "likes": 1650, "rts": 182, "replies": 150, "views": 176562, "ts": 1792596928, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/1280x720/gWYFthiwwWF08h-Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/3840x2160/8zOdSj2LHhr7lcN5.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVKjsCrbsAATbKg.jpg", "dur": 2708}], "quote": null, "reply_to": null}, {"id": "2112967156036202769", "url": "https://x.com/haider1/status/2112967156036202769", "text": "OpenAI CEO Sam Altman:\n\n\"the biggest advantage we have is that we get the next generation of models before anybody else, and we have time internally to use them and see what's going to work\"\n\nTake the math results. I don’t think any model currently widely available can get close to that", "name": "Haider.", "handle": "haider1", "avatar": "https://pbs.twimg.com/profile_images/2047286007003848704/u2mzg86I_200x200.jpg", "likes": 349, "rts": 20, "replies": 21, "views": 24210, "ts": 1792605601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112943247287050243/vid/avc1/720x720/xVw2jtP0fygLEmsD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112943247287050243/vid/avc1/2160x2160/53uHmLPGNFLfarFL.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112943247287050243/img/g6Wuf0cfMzvAW6Yj.jpg", "dur": 37}], "quote": {"id": "2112930776811806874", "url": "https://x.com/MatthewBerman/status/2112930776811806874", "text": "My interview with Sam Altman (@sama):\n\n0:00 Intro\n0:52 When Will AI Discover New Treatments?\n3:31 Why AI Hasn’t Killed Coding Jobs\n11:47 Personal AI Assistants\n15:39 Why Are We Busier Than Ever?\n20:10 Why the AI Consciousness Debate Worries Sam\n26:09 ChatGPT Is Too Agreeable\n30:03 OpenAI’s Bet on Chips and Cheaper Compute\n34:20 Why AI Needs a New Kind of Computer\n37:41 Sam on Pressure: “Pick the Big Thing”\n42:18 Why “AI Will Cure Cancer” Isn’t Enough", "name": "Matthew Berman", "handle": "MatthewBerman", "avatar": "https://pbs.twimg.com/profile_images/2051399921467830272/9RGo_6vv_200x200.jpg", "likes": 1654, "rts": 182, "replies": 150, "views": 176645, "ts": 1792596928, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/1280x720/gWYFthiwwWF08h-Z.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112930035783139330/vid/avc1/3840x2160/8zOdSj2LHhr7lcN5.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVKjsCrbsAATbKg.jpg", "dur": 2708}], "quote": null, "reply_to": null}, "reply_to": null}], "category": "frontier AI / labs (OpenAI CEO interview)", "captured": 1792618773, "post_ids": ["2112930776811806874", "2112967156036202769"]}, {"headline": "Claude Opus 5.5 Fuels Creative Coding Projects Amid Rate Limit Challenges", "meta": "Today's News · News · ~180 posts", "url": "https://x.com/i/trending/2112998873656430741", "summary": "Opus 5.5 (1M context, $4/$20 per M tokens) powers creative coding; heavy users report stricter rate limits.", "posts": [{"id": "2112960564531986791", "url": "https://x.com/Mr_Salio/status/2112960564531986791", "text": "Claude Opus 5.5 limits are getting ROUGH\n\nOpus 5.5 got nerfed hard\n\n23% of my usage gone without even using it heavily 💀\n\nThe usage limits feel worse today than at any point since Opus 5.5 was Released \n\nLast week the limits were like unlimited\n\nAnyone else feeling worse today?", "name": "Salio", "handle": "Mr_Salio", "avatar": "https://pbs.twimg.com/profile_images/2027630388403965952/mgrd9d6O_200x200.jpg", "likes": 303, "rts": 13, "replies": 43, "views": 20283, "ts": 1792604030, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK-bgSWEAArQPz.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112957316580470883", "url": "https://x.com/LexnLin/status/2112957316580470883", "text": "Opus 5.5 is truly an incredible model. \n\nThis is my token usage across everything I've been building over the past 30 days.\n(experiments, tasteskill, tastecode, cinetic, earshot)", "name": "Leon Lin", "handle": "LexnLin", "avatar": "https://pbs.twimg.com/profile_images/2030215945751248896/UIEzJ9Vq_200x200.jpg", "likes": 143, "rts": 2, "replies": 17, "views": 5546, "ts": 1792603255, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK5fUEXcAAHSpx.png?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112958948521214248", "url": "https://x.com/shmidtqq/status/2112958948521214248", "text": "holy sh*t, Opus 5.5 just turned into a clean-room reverse engineering agent that works a closed app end to end while you watch\n\nno source code needed to start understanding it\n\nthe agent walks the whole pipeline by itself:\n\n-> IDENTIFY: maps an unknown binary into one architecture picture, not a wall of code \n-> TRACE: follows a single feature from the click to the output, step by step \n-> PRIORITIZE: ranks functions by relevance to the behavior, not by raw reference count \n-> SPECIFY: turns the findings into a clean-room spec that excludes any copied code \n-> TEST: generates 30 behavioral cases (normal, edge, error) and measures parity\n\nthe useful part:\n\nit never guesses. every function it reads and every claim it makes carries a citation you can re-check\n\nthe loop:\n\ninvestigate -> specify -> build -> test -> improve\n\none rule: point it only at software you own or are authorized to analyze\n\nsave this, then build your own analysis agent, run by your AI employee", "name": "shmidt", "handle": "shmidtqq", "avatar": "https://pbs.twimg.com/profile_images/2068398835886440449/CBfDKDgF_200x200.jpg", "likes": 83, "rts": 6, "replies": 11, "views": 2979, "ts": 1792603644, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112956841059635200/vid/avc1/720x912/H8JIOtBRoZFcp7GX.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112956841059635200/vid/avc1/1080x1368/T4UWyk_4q2HIp1jK.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112956841059635200/img/zz7YTV1f1Y5jaIZF.jpg", "dur": 56}], "quote": {"id": "2110052071454228751", "url": "https://x.com/mojeskoqq/status/2110052071454228751", "text": "reverse engineering is the f**king most dangerous skill on the internet right now...\n\nfull walkthrough in the article below ↓ https://x.com/i/article/2110040820254478336", "name": "mojesko", "handle": "mojeskoqq", "avatar": "https://pbs.twimg.com/profile_images/2068434168954978304/gFJZPH-g_200x200.jpg", "likes": 53, "rts": 2, "replies": 5, "views": 18912, "ts": 1791910591, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792614827, "post_ids": ["2112960564531986791", "2112957316580470883", "2112958948521214248"]}, {"headline": "Sentry Distributes $1 Million to Open Source Maintainers This Year", "meta": "Today's News · News · 66 posts", "url": "https://x.com/i/trending/2112998868409291089", "summary": "Sentry raised its budget to $1M: $495K via thanks.dev, $60K to the PSF; Open Source Pledge now 37 companies, $7.4M paid.", "posts": [{"id": "2112954674466709784", "url": "https://x.com/zeeg/status/2112954674466709784", "text": "I am here once again to say “put up or shut up”\n\nOne million to open source this year, as we continue to give back to the ecosystem via the pledge. \n\nMore than half has gone directly to your favorite open source developers. \n\nhttps://blog.sentry.io/another-year-another-1-000-000-to-open-source-maintainers/", "name": "David Cramer", "handle": "zeeg", "avatar": "https://pbs.twimg.com/profile_images/1911613315765133312/HVkULegC_200x200.jpg", "likes": 317, "rts": 40, "replies": 30, "views": 23920, "ts": 1792602625, "media": [], "quote": null, "reply_to": null}, {"id": "2112975017298526308", "url": "https://x.com/bentlegen/status/2112975017298526308", "text": "it brings me tremendous peace that not only did Sentry become a huge software company\n\nbut it did so without abandoning its values or forgetting where it came from\n\na real unicorn company", "name": "Ben Vinegar", "handle": "bentlegen", "avatar": "https://pbs.twimg.com/profile_images/1765244446650568704/zgjmJiTX_200x200.jpg", "likes": 92, "rts": 2, "replies": 2, "views": 2970, "ts": 1792607475, "media": [], "quote": {"id": "2112954674466709784", "url": "https://x.com/zeeg/status/2112954674466709784", "text": "I am here once again to say “put up or shut up”\n\nOne million to open source this year, as we continue to give back to the ecosystem via the pledge. \n\nMore than half has gone directly to your favorite open source developers. \n\nhttps://blog.sentry.io/another-year-another-1-000-000-to-open-source-maintainers/", "name": "David Cramer", "handle": "zeeg", "avatar": "https://pbs.twimg.com/profile_images/1911613315765133312/HVkULegC_200x200.jpg", "likes": 317, "rts": 40, "replies": 30, "views": 23912, "ts": 1792602625, "media": [], "quote": null, "reply_to": null}, "reply_to": null}], "captured": 1792614827, "post_ids": ["2112954674466709784", "2112975017298526308"]}, {"headline": "Kling 4.0 Launches with 30-Second AI Video Upgrades", "meta": "Today's News · Kling 4.0 Launches with 30-Second AI Video Upgrades · Trending now · News · 942 posts", "url": "https://x.com/i/trending/2113009584319152573", "summary": "Kling 4.0 brings native 30-second scenes, omni reference for up to 15 assets like images and voice clips, and keyframe control for start, middle, and end frames. Platforms like Higgsfield, Magnific, and OpenArt integrated it quickly, alongside a new official API for developers. Users call it a game changer for reliable long takes, better motion, and professional workflows in ads and short films, with 4K and HDR features coming soon.", "posts": [{"id": "2112923547563917801", "url": "https://x.com/higgsfield/status/2112923547563917801", "text": "Kling is back.\n\nKling 4.0 is now live on Higgsfield.\n\n> Omni Reference: characters, objects and audio in one generation\n> 30-second scenes in a single pass\n> Start, middle and end frames to direct every beat\n> Native 4K coming soon\n\nAvailable now on Higgsfield.", "name": "Higgsfield AI 🧩", "handle": "higgsfield", "avatar": "https://pbs.twimg.com/profile_images/2029949430317637632/6qPl4MTS_200x200.jpg", "likes": 1230, "rts": 422, "replies": 166, "views": 962410, "ts": 1792595204, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112922956435484672/vid/avc1/1280x720/h4jClTdnbQeXurB1.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112922956435484672/vid/avc1/1920x1080/N_XjrT0_e4YGBaRk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112922956435484672/img/MtBMivzJkhy19WhN.jpg", "dur": 36}], "quote": null, "reply_to": null}, {"id": "2112962027140284515", "url": "https://x.com/VraserX/status/2112962027140284515", "text": "Hollywood is COOKED. 💀\n\nKling 4.0 just dropped and the results are literally indistinguishable from reality.\n\n“AI slop” is becoming a thing of the past.\n\nWe’re witnessing the death of traditional filmmaking in real time.", "name": "VraserX e/acc", "handle": "VraserX", "avatar": "https://pbs.twimg.com/profile_images/2052736242949701635/ARWmPNnJ_200x200.jpg", "likes": 417, "rts": 17, "replies": 16, "views": 21072, "ts": 1792604378, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112922121399660544/pu/vid/avc1/640x360/wsUjgbCHt067tVID.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112922121399660544/pu/vid/avc1/1280x720/M9-4qpPe7w1LFXea.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112922121399660544/pu/img/_grGRBwFAhIibGPM.jpg", "dur": 32}], "quote": null, "reply_to": null}], "category": "AI creative video tool", "captured": 1792618773, "post_ids": ["2112923547563917801", "2112962027140284515"]}, {"headline": "Tesla Beats Q3 Earnings with FSD Subscription Surge", "meta": "Explore · News · Trending now · News · 3,534 posts", "url": "https://x.com/i/trending/2113004223549874621", "summary": "Tesla reported $28.05B revenue and $0.48 EPS on 486,532 vehicle deliveries. FSD subscriptions jumped 67% YoY to 1.74M, with a 75% FSD attach rate in North America. The thread also covers Optimus progress and renewed Tesla-SpaceX merger speculation.", "posts": [{"id": "2112998455383847332", "url": "https://x.com/Tesla/status/2112998455383847332", "text": "Q3 Shareholder Update → http://ir.tesla.com\n\nHighlights\n– FSD Supervised attach rate grew to over 75% of new vehicle deliveries in NA\n\n– Unveiled the next-gen Roadster\n\n– Record deliveries in Canada, Australia, Japan & Taiwan\n\n– Tesla Semi now in volume production. Top variant can go up to 500 miles at a full 82,000 lbs while achieving efficiency of 1.7 kWh/mile – about a third of the energy a comparable diesel truck burns for the same load\n\n– Ended the quarter with the largest backlog for our passenger vehicles in 4 years!\n\nFSD Supervised\n– 4 new approvals since Q2 (Croatia, Slovenia, Czech Republic, Slovakia)\n– FSD is now live in nine EU countries & used by over 100,000 customers logging more than 160 million kilometers since initial approval\n\nRobotaxi\n– Deployed Cybercab into our Austin fleet\n– Hit nearly 2 million cumulative unsupervised miles, 8x growth in the quarter\n– Austin service now runs 6 am to midnight, with wait times continuing to come down as we add cars & improve the orchestration algorithms\n– Added Grok to Cybercab with Grok Bot & Connectors, letting you interface with your inbox, calendar, files, chats and tasks, all by voice. \n\nTransport, office & living room in one\n\nRobotics\n– Started production of @Tesla_Optimus on our high-volume lines in Fremont. \nThese are the first production-quality bots we've built, proving that the current manufacturing process for Optimus is suitable for a commercial product\n\nSI Compute\n– On track for 400 MW of training compute by year end, feeding both vehicle & humanoid autonomy\n– Austin Fab construction continues, equipment commissioning planned for 2027\n\nBattery\n– Battery supply is still the limiter on how fast we ramp vehicles globally, so we're expanding on every front: pack capacity in Berlin, cathode and lithium refining in Texas, LFP cells in Nevada\n– Shipped the first Megapacks built entirely with our own LFP cells\n– Increasing 4680 output to support ramp of Cybercab, Semi & Model Y\n\nEnergy\n– Megafactory Texas is up & running, with Megapack 3 production started\n– Highest-ever order rate & backlog for energy storage\n\nGrid constraints & power availability are making Megapack the answer for SI infrastructure demand: it excels at supplying large data center loads, smooths out demand spikes, helps new projects meet grid connection rules & makes the grid itself more stable\n\nAll with less local fossil fuel generation\n\nSupporting Infrastructure\n– Added 2,100+ net new Supercharger stalls, up 14% year over year", "name": "Tesla", "handle": "Tesla", "avatar": "https://pbs.twimg.com/profile_images/1337607516008501250/6Ggc4S5n_200x200.png", "likes": 8755, "rts": 978, "replies": 312, "views": 1165345, "ts": 1792613064, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLfv_XbQAAmvdB.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLfv_Ua8AAZQ8b.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLfv_bbEAAzUWE.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLfv_Yb0AIXJac.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2112999915962146924", "url": "https://x.com/WatcherGuru/status/2112999915962146924", "text": "JUST IN: Tesla $TSLA reveals none of its $972,000,000 Bitcoin was sold in Q3 2026.", "name": "Watcher.Guru", "handle": "WatcherGuru", "avatar": "https://pbs.twimg.com/profile_images/1641221212578754562/DfiC0KW2_200x200.png", "likes": 5923, "rts": 398, "replies": 243, "views": 271607, "ts": 1792613412, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLiOZsXQAANBsh.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLiOZyXgAAGbpF.jpg?name=orig"}], "quote": null, "reply_to": null}, {"id": "2113000312592072933", "url": "https://x.com/SawyerMerritt/status/2113000312592072933", "text": "Tesla says they have officially started Optimus production in Fremont on their high-volume lines.\n\n\"The bots coming off this line are the first production quality bots that we have manufactured. While we will continue to iterate on the hardware and manufacturing process, we have proven that the current manufacturing process for Optimus is suitable for a commercial product.\"", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 4951, "rts": 453, "replies": 138, "views": 126189, "ts": 1792613506, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLiXaeWgAAESwi.jpg?name=orig"}], "quote": null, "reply_to": null}], "captured": 1792617122, "post_ids": ["2112998455383847332", "2112999915962146924", "2113000312592072933"]}]);